	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_LAGERAUFGABE_WA primary key (MANDANT_ID, LAGERNUMMER_ID, LAGERAUFGABE_ID, HANDLING_UNIT_ID_NACH)
)COMMENT='Aggregated table that stores the result of joining LAGERAUFGABE_2 , BESCH_LIEF_WA_DET_2, LAGERAUFTRAG_2, PROTOKOLL_VERLADUNG_EWM_2, BESCH_LIEF_2\n             This table contains 1 rows per Warehouse (lagernummer_id), Warehouse Task (lageraufgabe_id), Handling Unit_2 that is the destination of the task (handling_unit_id_nach) and Mandant_2'
